            writer.WritePropertyName("ask_depth");
            JsonSerializer.Serialize(writer, v2OrderBookSnapshot.AskDepth, jsonSerializerOptions);
            writer.WriteString("observed_at", v2OrderBookSnapshot.ObservedAt.ToString(ObservedAtFormat));

            writer.WritePropertyName("freshness");
            JsonSerializer.Serialize(writer, v2OrderBookSnapshot.Freshness, jsonSerializerOptions);
            if (v2OrderBookSnapshot.BidOption.IsSet)
                writer.WriteString("bid", v2OrderBookSnapshot.Bid);

            if (v2OrderBookSnapshot.AskOption.IsSet)
                writer.WriteString("ask", v2OrderBookSnapshot.Ask);

            if (v2OrderBookSnapshot.SpreadOption.IsSet)
            {
                writer.WritePropertyName("spread");
                JsonSerializer.Serialize(writer, v2OrderBookSnapshot.Spread, jsonSerializerOptions);
            }
            if (v2OrderBookSnapshot.BuyOrderCountOption.IsSet)
                writer.WriteNumber("buy_order_count", v2OrderBookSnapshot.BuyOrderCountOption.Value!.Value);

            if (v2OrderBookSnapshot.SellOrderCountOption.IsSet)
                writer.WriteNumber("sell_order_count", v2OrderBookSnapshot.SellOrderCountOption.Value!.Value);

            if (v2OrderBookSnapshot.SlippageOption.IsSet)
                writer.WriteString("slippage", v2OrderBookSnapshot.Slippage);

            if (v2OrderBookSnapshot.LiquidityScoreOption.IsSet)
                writer.WriteNumber("liquidity_score", v2OrderBookSnapshot.LiquidityScoreOption.Value!.Value);
        }
    }
}
